import React, { useState } from 'react';

const JourneyShareTab = () => {
  const [searchBoard, setSearchBoard] = useState('');
  const [searchKeyword, setSearchKeyword] = useState('');

  // 가상의 내가 쓴 리뷰 (총 글 수)
  const [myReviews] = useState([
    { id: 1, title: '해인사 템플스테이 정말 좋았어요!', date: '2025-06-20' },
    { id: 2, title: '경주 불국사 야경은 최고!', date: '2025-05-15' },
    { id: 3, title: '통도사 봄꽃 구경', date: '2025-04-01' },
  ]);

  // 가상의 내가 쓴 댓글 (총 댓글 수)
  const [myComments] = useState([
    { id: 1, content: '맞아요, 저도 거기 정말 감동적이었어요.', board: '리뷰', parentPost: '해동용궁사' },
    { id: 2, content: '궁금했던 정보 감사해요!', board: '사찰정보', parentPost: '범어사' },
    { id: 3, content: '다음에 저도 꼭 가봐야겠어요!', board: '리뷰', parentPost: '금산사' },
  ]);

  const handleCommentSearch = (e) => {
    e.preventDefault();
    // 여기에 실제 댓글 검색 API 호출 로직
    alert(`댓글 검색 조건: 게시판 - ${searchBoard}, 키워드 - "${searchKeyword}"로 검색! (API 연동 필요)`);
    console.log('댓글 검색 조건:', { searchBoard, searchKeyword });
  };

  return (
    <div className="tab-content-section journey-share-tab">
      <h3 className="tab-content-title">여정 나누기 ✍️</h3>

      <h4>내가 쓴 리뷰 보기 (총 {myReviews.length}개)</h4>
      <div className="post-list">
        {myReviews.length > 0 ? (
          myReviews.map(review => (
            <div key={review.id} className="post-item">
              <span className="post-title">{review.title}</span>
              <span className="post-meta">{review.date}</span>
              <button className="action-button">자세히 보기</button>
            </div>
          ))
        ) : (
          <p>작성한 리뷰가 없어요. 😢</p>
        )}
      </div>

      <h4 style={{marginTop: '40px'}}>내가 작성한 댓글 보기 (총 {myComments.length}개)</h4>
      <form onSubmit={handleCommentSearch} className="search-form">
        <select value={searchBoard} onChange={(e) => setSearchBoard(e.target.value)}>
          <option value="">게시판 선택</option>
          <option value="사찰정보">사찰정보</option>
          <option value="리뷰">리뷰</option>
        </select>
        <input
          type="text"
          placeholder="검색 키워드 입력"
          value={searchKeyword}
          onChange={(e) => setSearchKeyword(e.target.value)}
        />
        <button type="submit" className="search-button">검색</button>
      </form>
      <div className="comment-list">
        {myComments.length > 0 ? (
          myComments.map(comment => (
            <div key={comment.id} className="comment-item">
              <span className="comment-content">
                [{comment.board}] "{comment.parentPost}" 글에 작성: {comment.content}
              </span>
              <button className="action-button">자세히 보기</button>
            </div>
          ))
        ) : (
          <p>작성한 댓글이 없어요. 😢</p>
        )}
      </div>
    </div>
  );
};

export default JourneyShareTab;
